# @generated by skyramp
# Contract test for GET /api/recipes/{slug}.
# Asserts the recipeServings response field is an integer count.
import os
import re
import uuid

import requests

BASE_URL = os.getenv("SKYRAMP_TEST_BASE_URL", "http://localhost:9000")
TOKEN = os.getenv("SKYRAMP_TEST_TOKEN", "")

UUID_RE = re.compile(r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$", re.I)


def _headers():
    return {"Authorization": f"Bearer {TOKEN}"} if TOKEN else {}


def _create_recipe(headers):
    """Creates a recipe with a run-unique name and returns (slug, name)."""
    suffix = uuid.uuid4().hex[:12]
    name = f"skyramp servings contract {suffix}"
    resp = requests.post(f"{BASE_URL}/api/recipes", headers=headers, json={"name": name}, timeout=10)
    assert resp.status_code == 201, f"recipe create failed: {resp.status_code} {resp.text}"
    slug = resp.json()
    assert slug == f"skyramp-servings-contract-{suffix}"
    return slug, name


def _delete_recipe(headers, slug):
    requests.delete(f"{BASE_URL}/api/recipes/{slug}", headers=headers, timeout=10)


def test_recipe_summary_recipe_servings_is_int():
    headers = _headers()
    slug, name = _create_recipe(headers)
    try:
        patch = requests.patch(
            f"{BASE_URL}/api/recipes/{slug}",
            headers=headers,
            json={"slug": slug, "recipeServings": 4},
            timeout=10,
        )
        assert patch.status_code == 200, f"patch failed: {patch.status_code} {patch.text}"
        patched = patch.json()
        assert patched["recipeServings"] == 4
        assert patched["slug"] == slug

        resp = requests.get(f"{BASE_URL}/api/recipes/{slug}", headers=headers, timeout=10)
        assert resp.status_code == 200
        body = resp.json()

        # recipeServings is serialized as an integer count (e.g. 4 servings)
        assert "recipeServings" in body, "recipeServings is absent from the response body"
        assert isinstance(body["recipeServings"], int)
        assert not isinstance(body["recipeServings"], bool)
        assert body["recipeServings"] == 4
        assert body["slug"] == slug
        assert body["name"] == name
        assert UUID_RE.match(body["id"]), f"id is not a uuid: {body['id']}"
    finally:
        _delete_recipe(headers, slug)


def test_recipe_servings_rejects_fractional_value():
    """A whole-number servings count cannot carry a fractional part."""
    headers = _headers()
    slug, _name = _create_recipe(headers)
    try:
        resp = requests.patch(
            f"{BASE_URL}/api/recipes/{slug}",
            headers=headers,
            json={"slug": slug, "recipeServings": 2.5},
            timeout=10,
        )
        assert resp.status_code == 422, f"expected 422, got {resp.status_code} {resp.text}"
        assert resp.json()["detail"], "422 response carries no detail"
        detail = resp.json()["detail"]
        assert len(detail) == 1, f"expected exactly one field error, got {detail}"
        assert detail[0]["loc"] == ["body", "recipeServings"]
        assert detail[0]["input"] == 2.5
    finally:
        _delete_recipe(headers, slug)
